def transform(grid):
    W = len(grid[0])
    H = len(grid)
    result = [row[:] for row in grid]

    visited = set()

    for start_r in range(H):
        for start_c in range(W):
            if grid[start_r][start_c] == 5 and (start_r, start_c) not in visited:
                # BFS to get connected component
                component = []
                stack = [(start_r, start_c)]
                seen = {(start_r, start_c)}
                while stack:
                    r, c = stack.pop()
                    component.append((r, c))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < H and 0 <= nc < W and (nr, nc) not in seen and grid[nr][nc] == 5:
                            seen.add((nr, nc))
                            stack.append((nr, nc))

                visited.update(seen)

                # Bounding box
                rows = [r for r, _ in component]
                cols = [c for _, c in component]
                min_r, max_r = min(rows), max(rows)
                min_c, max_c = min(cols), max(cols)

                # Interior rows (between top and bottom)
                interior_rows = list(range(min_r + 1, max_r))

                # Find wall columns: cols with 5s in ALL interior rows
                # Add min_c and max_c as walls
                wall_cols = set()
                if len(interior_rows) > 0:
                    for c in range(min_c, max_c + 1):
                        if all(result[rr][c] == 5 for rr in interior_rows):
                            wall_cols.add(c)
                wall_cols.add(min_c)
                wall_cols.add(max_c)
                wall_cols = sorted(wall_cols)

                # Fill 2s between wall columns, for top row and interior rows
                for fc in range(min_r, max_r):
                    seen_boundary = set()
                    # Identify boundary areas between wall columns
                    for i, wall_c in enumerate(wall_cols):
                        # The area adjacent to this wall
                        if wall_c > 0:
                            seen_boundary.add(wall_c - 1)
                    for c in seen_boundary:
                        if c >= min_c and c < max_c and result[fc][c] == 0:
                            result[fc][c] = 2

                # Filler row above (row min_r - 1)
                filler_r = min_r - 1
                if filler_r >= 0:
                    filler_start = max(0, min_c - 2)
                    filler_end = min(W - 1, max_c - 1)
                    for c in range(filler_start, filler_end + 1):
                        if result[filler_r][c] == 0:
                            result[filler_r][c] = 2

    return result

